tasks.solution:
-- 이 조인을 고쳐 공급처가 없는 물건도 결과에 남기세요.
-- LEFT JOIN은 왼쪽 items의 행을 모두 남기고, 맞는 공급처가 없으면 NULL로 채워요.
SELECT i.id, s.name FROM items i LEFT JOIN suppliers s ON i.supplier = s.id ORDER BY i.id;

